export function HomebrewText({text,character,onResource}:{text:string;character?:ExportCharacter;onResource?:(id:string,amount:number)=>void}){
 const [result,setResult]=useState('');
 const parts=text.split(/(\[\[[^\]]+\]\])/g);
 return <div className="hb-rich">{parts.map((part,i)=>{if(!part.startsWith('[['))return <span key={i}>{part}</span>;const name=/^\[\[(\w+)/.exec(part)?.[1]||'';const params=Object.fromEntries([...part.matchAll(/(\w+)="([^"]*)"/g)].map(m=>[m[1],m[2]]));const label=params.label||params.text||params.id||name;
  return <button type="button" key={i} onClick={()=>{try{if(['consume','restore'].includes(name)){if(!onResource)throw Error('Доступно на игровом листе');onResource(params.resource,Number(params.amount||1)*(name==='restore'?-1:1));setResult('Ресурс обновлён');}else if(params.formula&&character){setResult(label+': '+evaluateFormula(params.formula,{...hbContext(character),roll:!['value','dc'].includes(name)}));}else setResult(label); }catch(e){setResult((e as Error).message);}}}>{label}</button>;})}{result&&<output role="status">{result}</output>}</div>;
}
